  "Kami belum menerima konfirmasi dari penyedia pembayaran. Bila Anda sudah membayar, statusnya akan diperbarui otomatis dalam beberapa menit — tidak perlu membayar ulang.": "We have not received confirmation from the payment provider yet. If you have already paid, the status will update automatically within a few minutes — there is no need to pay again.",
