  "Kenapa ada tahap pembelajaran?": "Why is there a learning stage?",
  "Mitra EXOCLEAN bekerja di rumah dan gedung orang lain, sering dengan chemical dan di ketinggian. Pembelajaran ini memastikan Anda pulang selamat, hasil kerja Anda lulus penilaian mutu, dan klien mempercayakan pekerjaannya kembali kepada Anda. Sertifikat yang terbit tercantum di profil dan menjadi dasar penugasan pekerjaan khusus seperti rope access dan cuci AC.": "EXOCLEAN partners work in other people's homes and buildings, often with chemicals and at height. This training makes sure you come home safe, that your work passes quality assessment, and that clients trust you with their work again. Certificates issued are shown on your profile and form the basis for assigning specialist work such as rope access and AC cleaning.",
