  "Anda masuk sebagai <b>Klien</b> — bisa langsung memesan layanan dan berbelanja perlengkapan.": "You are signed in as a <b>Client</b> — you can order services and shop for supplies right away.",
  "Ingin lebih? Di menu <b>Profil</b> Anda bisa mendaftar menjadi <b>Mitra Lapangan</b>, <b>Mitra Toko</b>, <b>Affiliate</b>, atau <b>Dropshipper</b> — kapan saja, tanpa membuat akun baru.": "Want more? Under <b>Profile</b> you can register as a <b>Field Partner</b>, <b>Store Partner</b>, <b>Affiliate</b>, or <b>Dropshipper</b> — any time, without creating a new account.",
