  "Mode simulasi.": "Simulation mode.",
  "OTP tampil di layar dan pemilih akun Google/Facebook ditiru. Seluruh alur dan batasnya sama dengan aslinya — hanya pengirimannya yang belum nyata.": "The OTP appears on screen and the Google/Facebook account picker is mimicked. The whole flow and its limits match the real thing — only the delivery is not real yet.",
