  "Batas yang hanya ada di browser bisa dilewati siapa pun yang membuka konsol. Karena itu pada mode nyata seluruh batas ini ditegakkan ulang oleh server — angka di sini hanya menyamakan tampilannya.": "A limit that exists only in the browser can be bypassed by anyone who opens the console. That is why in real mode every one of these limits is enforced again by the server — the numbers here only keep the display consistent.",
