  "jam kerja": "working hours",
  "Dana dipotong dari saldo begitu penarikan diajukan, dan dikembalikan utuh bila Anda batalkan atau admin menolaknya. Jadi angka “saldo tersedia” selalu menunjukkan dana yang benar-benar bisa Anda pakai.": "Funds are deducted from your balance as soon as a withdrawal is requested, and returned in full if you cancel or an admin rejects it. So the \"available balance\" figure always shows money you can genuinely use.",
  "Keamanan penarikan": "Withdrawal security",
  "PIN terkunci 15 menit setelah 5 kali salah": "The PIN locks for 15 minutes after 5 wrong attempts",
  "Tidak lewat telepon, WhatsApp, maupun admin di lapangan. Siapa pun yang meminta PIN Anda sedang mencoba menipu.": "Not by phone, WhatsApp, or an admin on site. Anyone asking for your PIN is trying to defraud you.",
