  "PIN terkunci. Coba lagi dalam ": "PIN locked. Try again in ",
  "Lengkapi 6 angka PIN": "Enter all 6 PIN digits",
  "PIN berbeda dari kata sandi. Kata sandi membuka aplikasi, PIN menyetujui perpindahan uang — jadi sandi yang bocor tidak otomatis berarti saldo Anda bisa ditarik orang lain.": "The PIN is different from your password. The password opens the app, the PIN approves money moving — so a leaked password does not automatically mean someone can withdraw your balance.",
  "PIN transaksi aktif": "Transaction PIN active",
  "Buka aplikasi authenticator di ponsel Anda — Google Authenticator, Microsoft Authenticator, Authy, atau bawaan pengelola kata sandi.": "Open the authenticator app on your phone — Google Authenticator, Microsoft Authenticator, Authy, or the one built into your password manager.",
  "Pastikan jam ponsel Anda diatur otomatis. Kode ini dihitung dari waktu, jadi jam yang meleset lebih dari satu menit akan membuat kodenya selalu ditolak.": "Make sure your phone's clock is set automatically. This code is derived from the time, so a clock more than a minute out will make the code always be rejected.",
  "Authenticator aktif. Akun Anda sekarang terlindungi kode yang berganti tiap 30 detik.": "Authenticator active. Your account is now protected by a code that changes every 30 seconds.",
  "Ini satu-satunya kesempatan melihat kode ini. Simpan di tempat aman — kode inilah jalan masuk Anda bila ponsel authenticator hilang atau rusak. Setiap kode hanya bisa dipakai satu kali.": "This is the only time you will see this code. Store it somewhere safe — this code is your way back in if your authenticator phone is lost or broken. Each code can only be used once.",
  "Unduh": "Download",
  "Masukkan kode dulu": "Enter the code first",
  "Kode pemulihan dipakai. Sisa ": "Recovery code used. ",
  "kode.": "codes left.",
  "Perangkat": "Device",
  "Semua jalur pemulihan membutuhkan authenticator atau kode pemulihan. Email saja tidak pernah cukup — justru email yang mungkin sedang tidak bisa Anda buka.": "Every recovery path requires an authenticator or a recovery code. Email alone is never enough — email may well be the very thing you cannot open.",
  "Akun ": "Account ",
  "Hubungi admin EXOCLEAN untuk verifikasi manual dengan membawa identitas yang sama dengan yang terdaftar.": "Contact an EXOCLEAN admin for manual verification, bringing the same ID you registered with.",
  "Hubungi Admin": "Contact an Admin",
  "Masukkan nomor WhatsApp yang Anda daftarkan. Kami akan mencocokkannya dengan akun yang ada, lalu meminta kode authenticator sebelum menampilkan emailnya.": "Enter the WhatsApp number you registered. We will match it against the existing account, then ask for your authenticator code before showing the email.",
  "Terverifikasi.": "Verified.",
  "Masuk sekarang": "Sign in now",
  "Masukkan email atau nomor WhatsApp terdaftar. Kata sandi baru hanya bisa dipasang setelah Anda membuktikan kepemilikan lewat authenticator.": "Enter your registered email or WhatsApp number. A new password can only be set after you prove ownership via your authenticator.",
  "Setelah diganti, semua perangkat lain akan dikeluarkan otomatis. Anda perlu memverifikasi ulang di sana.": "Once changed, all other devices are signed out automatically. You will need to verify again there.",
  "Kata sandi diperbarui": "Password updated",
  "Butuh authenticator": "Authenticator required",
  "PIN hanya bisa disetel ulang lewat authenticator, karena PIN adalah gerbang terakhir sebelum saldo Anda berpindah. Pasang authenticator dulu di Profil → Keamanan, atau hubungi admin untuk verifikasi manual.": "A PIN can only be reset via an authenticator, because the PIN is the last gate before your balance moves. Set up an authenticator first under Profile → Security, or contact an admin for manual verification.",
  "Lanjut": "Continue",
  "Kata sandi salah": "Wrong password",
  "Tentukan PIN baru": "Set a new PIN",
  "Semakin banyak lapis yang aktif, semakin sulit akun Anda diambil alih orang lain.": "The more layers you enable, the harder your account is for someone else to take over.",
  "Terkunci ": "Locked ",
