  "PIN tersimpan sebagai turunan PBKDF2 ber-salt — tidak ada layar mana pun, termasuk milik admin, yang bisa menampilkannya kembali.": "The PIN is stored as a salted PBKDF2 derivation — no screen anywhere, including an admin's, can show it again.",
