  "Mode live tanpa URL backend.": "Live mode with no backend URL.",
  "Mode simulasi aktif.": "Simulation mode active.",
  "Tarif kurir di bawah dibuat aplikasi dari jarak — bukan tarif sungguhan, dan nomor resinya tidak bisa dilacak di situs kurir. Cukup untuk mencoba seluruh alur tanpa API key.": "The courier rates below are generated by the app from distance — not real rates, and their tracking numbers cannot be traced on the courier's site. Enough to try the whole flow without an API key.",
  "Kunci itu berhak membuat pesanan kirim — artinya berhak mengeluarkan uang. Tempatnya hanya di berkas .env pada server, dan halaman ini menolak nilai yang terlihat seperti kunci. Yang disimpan di aplikasi hanyalah alamat backend dan pilihan kurir.": "That key can create shipments — meaning it can spend money. Its only home is the .env file on the server, and this page rejects values that look like a key. All the app stores is the backend address and the courier selection.",
  "Mode pengiriman": "Shipping mode",
  "Biteship (kurir sungguhan)": "Biteship (real couriers)",
  "Backend pengiriman": "Shipping backend",
  "URL backend": "Backend URL",
  "kurir dipilih": "couriers selected",
  "Yang benar-benar muncul adalah irisan antara pilihan di sini dan kurir yang aktif di akun Biteship Anda. Kurir instan (GoSend, GrabExpress, Lalamove) hanya melayani jarak dekat dan menghitung tarif per kilometer.": "What actually appears is the overlap between the choices here and the couriers active on your Biteship account. Instant couriers (GoSend, GrabExpress, Lalamove) only serve short distances and charge by the kilometre.",
  "Mitra toko memakai alamat tokonya masing-masing; alamat ini hanya dipakai Toko Resmi dan sebagai cadangan bila alamat toko belum diisi.": "Store partners use their own store address; this address is only used by the Official Store and as a fallback when a store address is empty.",
  "Ukuran & berat bawaan": "Default size & weight",
  "Berat (gram)": "Weight (grams)",
  "Panjang (cm)": "Length (cm)",
  "Lebar (cm)": "Width (cm)",
  "Tinggi (cm)": "Height (cm)",
  "Kurir menagih menurut berat volumetrik — panjang × lebar × tinggi ÷ 6000 — bila angkanya lebih besar daripada berat sebenarnya. Karena itu dimensi tetap perlu diisi meski barangnya ringan.": "Couriers charge by volumetric weight — length × width × height ÷ 6000 — when that figure is larger than the actual weight. That is why dimensions still need filling in even for light goods.",
  "URL backend disimpan.": "Backend URL saved.",
  "Isi URL backend dulu.": "Enter the backend URL first.",
  "Minimal satu kurir harus dipilih.": "At least one courier must be selected.",
  "Ukuran bawaan disimpan.": "Default size saved.",
  "Data pengiriman": "Shipping data",
  "Ongkir yang ditagihkan ke pembeli bisa meleset dari tagihan kurir selama angka ini belum benar.": "The shipping charged to the buyer can differ from the courier's bill for as long as these figures are wrong.",
  "Kurir menagih menurut yang LEBIH BESAR antara berat timbangan dan berat volumetrik — panjang × lebar × tinggi ÷ ": "Couriers charge by the GREATER of the scale weight and the volumetric weight — length × width × height ÷ ",
  ". Satu karton tisu ringan tetapi besar dibayar menurut ukurannya, bukan timbangannya. Karena itu dimensi tetap perlu meski barangnya enteng.": ". A carton of tissues is light but bulky and is charged by its size, not its weight. That is why dimensions still matter even for light goods.",
