  "Riwayat di bawah disusun aplikasi dari cap waktu pesanan — bukan data kurir sungguhan.": "The history below is assembled by the app from order timestamps — not real courier data.",
  "sertifikat kedaluwarsa.": "expired certificates.",
  "Setiap fungsi punya satu kursus sertifikasi. Setelah lulus, pekerjaan pada layanan tersebut mulai masuk ke jadwal Anda.": "Each function has one certification course. Once passed, work on that service starts appearing in your schedule.",
  "Pilih sesuai minat dan kemampuan Anda. Tidak ada batas jumlah — tetapi setiap fungsi menuntut satu kursus sertifikasi yang harus benar-benar Anda lulusi.": "Choose according to your interest and ability. There is no limit — but every function demands one certification course you must genuinely pass.",
  "nilai min": "min. score",
  "Sertifikat berlaku sampai": "Certificate valid until",
  "Sertifikat Anda sudah lewat masa berlakunya. Ulangi kursus dan ujiannya untuk membuka kembali pekerjaan ini.": "Your certificate has expired. Retake the course and its exam to unlock this work again.",
  "Selesaikan dulu lima kursus wajib mitra. Kursus fungsi kerja terbuka setelah Anda menjadi mitra tersertifikasi.": "Finish the five required partner courses first. Work-function courses open once you are a certified partner.",
  "berlaku": "valid",
  "Daftar fungsi kerja": "Register a work function",
  "Fungsi kerja ini tergolong berisiko tinggi — materi keselamatannya lebih ketat dan sertifikatnya berlaku lebih singkat.": "This work function is high-risk — its safety material is stricter and its certificate is valid for a shorter time.",
  "Pendaftaran dibatalkan": "Registration cancelled",
  "Fungsi kerja": "Work function",
  "layanan dalam katalog": "services in the catalogue",
  "rata-rata": "average",
  "fungsi kerja belum punya mitra tersertifikasi.": "work functions have no certified partner.",
  "Risiko": "Risk",
  "Belum ada mitra yang tersertifikasi untuk fungsi ini. Pesanan pada layanannya belum bisa dijadwalkan — dorong mitra mengambil kursusnya, atau rekrut mitra baru dengan keahlian ini.": "No partners are certified for this function yet. Orders for its services cannot be scheduled — encourage partners to take the course, or recruit new partners with this skill.",
  "berlaku sampai": "valid until",
  "Penyaring isi sedang dimatikan.": "The content filter is currently off.",
  "Semua pesan lewat tanpa diperiksa, termasuk ancaman dan pelecehan. Nyalakan kembali kecuali Anda sedang menelusuri masalah.": "Every message passes unchecked, including threats and harassment. Switch it back on unless you are tracing a problem.",
  "Penyaring isi aktif.": "The content filter is active.",
  "ditolak sebelum terkirim": "blocked before sending",
  ". Makian selalu diperingatkan lalu ditutup bagi penerima, tidak pernah diblokir — menyamakannya dengan ancaman membuat orang belajar mengabaikan peringatan.": ". Profanity is always warned and then hidden from the recipient, never blocked — treating it the same as a threat teaches people to ignore warnings.",
  "Kategori berat": "Severe categories",
  "Catatan Pelanggaran": "Violation Log",
  "Setelan Penyaring": "Filter Settings",
  "Kamus & Pengecualian": "Dictionary & Exceptions",
  "Uji Kalimat": "Test a Sentence",
  "Setiap pesan yang tertangkap penyaring akan muncul di sini — termasuk yang hanya diperingatkan lalu tetap dikirim. Pola perilaku baru terlihat dari rekaman, bukan dari satu pesan.": "Every message caught by the filter appears here — including those only warned and still sent. A pattern of behaviour shows in the record, not in a single message.",
  "Catatan pelanggaran": "Violation log",
  "kejadian": "incidents",
  "diblokir": "blocked",
  "diperingatkan": "warned",
  "Kata terdeteksi": "Words detected",
  "Mode penyaring": "Filter mode",
  "Blokir (disarankan)": "Block (recommended)",
  "Ancaman, terorisme, konten seksual, pelecehan, dan hujatan SARA ditolak sebelum terkirim. Makian tetap hanya diperingatkan.": "Threats, terrorism, sexual content, harassment, and hate speech are blocked before sending. Profanity is still only warned.",
  "Peringatan saja": "Warn only",
  "Semua pesan tetap terkirim, tetapi pelanggarannya dicatat dan penerimanya melihat penandaan. Berguna saat menelusuri keluhan salah tangkap.": "Every message is still sent, but violations are logged and the recipient sees the flag. Useful when tracing complaints about false positives.",
  "Matikan penyaring": "Turn the filter off",
  "Berlaku untuk klien, mitra lapangan, dan mitra toko. Pegawai internal — admin dan supervisor — dikecualikan, karena merekalah kanal resmi perusahaan bila sebuah urusan memang harus lewat telepon.": "Applies to clients, field partners, and store partners. Internal staff — admins and supervisors — are exempt, because they are the company's official channel when something genuinely has to go by phone.",
  "Yang ditolak adalah bentuk nomor Indonesia (08…, +62…, 8…, dan telepon rumah), tautan wa.me, serta angka yang dieja seperti “kosong delapan satu dua…”. Nominal rupiah, nomor resi, dan nomor dokumen tidak ikut tertahan.": "What is blocked is the Indonesian number format (08…, +62…, 8…, and landlines), wa.me links, and digits spelled out like \"zero eight one two…\". Rupiah amounts, tracking numbers, and document numbers are not caught.",
  "Penyensoran tampilan": "Display censoring",
  "Tutupi kata kasar bagi penerima": "Hide rude words from the recipient",
  "Yang tersimpan selalu teks aslinya — kalau yang disimpan sudah disensor, bukti untuk penyelesaian sengketa ikut hilang. Penyensoran hanya terjadi saat pesan digambar. Pengirimnya sendiri dan pemegang izin moderasi tetap melihat teks utuh.": "What is stored is always the original text — if what is stored were already censored, the evidence for settling a dispute would be lost with it. Censoring happens only when a message is drawn. The sender themselves and holders of moderation permission still see the full text.",
  "Daftar bawaan sudah mencakup kata yang paling lazim. Yang Anda tambahkan di sini menumpuk di atasnya. Pengecualian dipakai untuk frasa kerja yang sah dan kebetulan mengandung kata bermuatan — misalnya “bunuh kuman”.": "The default list already covers the most common words. What you add here stacks on top of it. Exceptions are for legitimate work phrases that happen to contain a loaded word — \"kill germs\", for instance.",
  "Kata tambahan": "Extra words",
  "kata": "words",
  "Pengecualian": "Exceptions",
  "frasa tambahan": "extra phrases",
  "Bawaan": "Default",
  "Kamus bawaan": "Default dictionary",
  "kata terdaftar": "words listed",
  "Dicocokkan sebagai frasa berkonteks, bukan kata tunggal — supaya “bunuh kuman” tidak ikut tertangkap.": "Matched as a phrase in context, not as a single word — so \"kill germs\" is not caught.",
  "Uji kalimat": "Test a sentence",
