  "Pengecualian ditambahkan.": "Exception added.",
  "Obrolan terbuka otomatis begitu ada pekerjaan atau pesanan toko yang melibatkan Anda. Semua percakapan tersimpan dan bisa dibuka kembali kapan saja.": "Chat opens automatically as soon as there is a job or store order that involves you. All conversations are stored and can be reopened at any time.",
  "Mode pengawasan.": "Supervision mode.",
  "Anda dapat menelusuri percakapan milik klien dan mitra untuk keperluan penyelesaian sengketa. Setiap percakapan yang dibuka tercatat di log aktivitas, dan Anda tidak dapat ikut membalas.": "You may search conversations between clients and partners for the purpose of settling disputes. Every conversation you open is recorded in the activity log, and you cannot join in and reply.",
  "Setiap percakapan terikat pada satu pekerjaan atau pesanan, dan riwayatnya tidak hilang. Demi keamanan kedua pihak, nomor telepon tidak ditampilkan dan seluruh kesepakatan sebaiknya tetap tercatat di sini.": "Each conversation is tied to one job or order, and its history is not lost. For the safety of both sides, phone numbers are not shown and every agreement is best kept recorded here.",
