  "Browser ini memblokir penyimpanan berkas (biasanya karena mode penyamaran), jadi lampiran tidak bisa dikirim. Teks tetap bisa.": "This browser blocks file storage (usually because of private mode), so attachments cannot be sent. Text still works.",
  "Buang": "Discard",
