  "Terdeteksi": "Detected",
  "Seluruh percakapan sengaja dijaga tetap di dalam aplikasi — di sinilah riwayatnya tersimpan dan pembayarannya terlindungi. Untuk urusan yang butuh telepon, hubungi admin EXOCLEAN.": "Every conversation is deliberately kept inside the app — this is where the history is stored and the payment is protected. For matters that need a phone call, contact an EXOCLEAN admin.",
  "Pesan tetap bisa dikirim, tetapi bagian tersebut akan ditutup bagi penerima dan kejadiannya tercatat untuk ditinjau admin.": "The message can still be sent, but that part will be hidden from the recipient and the incident recorded for admin review.",
  "Periksa lagi sebelum mengirim.": "Check again before sending.",
  "Menyepakati pekerjaan atau pembayaran di luar aplikasi membuat Anda kehilangan jaminan, bukti, dan perlindungan bagi hasil.": "Agreeing on work or payment outside the app leaves you without the guarantee, the evidence, and the revenue-share protection.",
