  "Setiap perubahan di halaman ini berlaku untuk poin yang terbit SESUDAHNYA. Poin yang sudah di tangan pengguna memakai ketentuan yang berlaku saat ia diberikan — mengubah aturan tidak pernah menyusutkan poin orang.": "Every change on this page applies to points issued AFTERWARDS. Points already in users' hands keep the terms that applied when they were given — changing the rules never shrinks anyone's points.",
