  "Ubah angkanya langsung di baris di bawah. Perubahan berlaku untuk poin yang terbit sesudahnya; poin yang sudah di tangan pelanggan tidak ikut berubah.": "Edit the numbers directly in the rows below. Changes apply to points issued afterwards; points already in customers' hands do not change.",
  "Poin mitra yang dikaitkan pada jumlah pekerjaan akan mendorong orang mengejar volume dan mengorbankan hasil. Karena itu bobot terbesar ada pada lulus QC dan nilai lima dari klien.": "Partner points tied to job counts push people to chase volume and sacrifice quality. That is why the greatest weight sits on passing QC and scoring five from the client.",
  "bulan terakhir — bukan dari saldo. Kalau memakai saldo, menukarkan poin akan menurunkan jenjang, dan pelanggan jadi menimbun poin alih-alih memakainya.": "the last months — not from the balance. If it used the balance, redeeming points would lower the tier, and customers would hoard points instead of using them.",
