  "Item yang memberi nilai rupiah lebih besar daripada poin × nilai tukar berarti menjual di bawah harga — periksa tiap item sebelum menayangkannya.": "An item worth more in rupiah than points × the exchange rate is being sold below cost — check every item before publishing it.",
  "Ketentuan umum": "General terms",
  "Mematikan program menghentikan perolehan dan penukaran, tetapi saldo pengguna tidak dihapus — poin adalah utang perusahaan, bukan angka hiasan.": "Turning the programme off stops earning and redemption, but user balances are not deleted — points are a company liability, not a decorative number.",
