  "Penyesuaian tercatat atas nama Anda dan muncul di riwayat pengguna. Pakai untuk memperbaiki kesalahan atau memberi apresiasi khusus — bukan sebagai jalan pintas mengganti aturan.": "The adjustment is recorded under your name and appears in the user's history. Use it to correct a mistake or give special recognition — not as a shortcut around the rules.",
