  "Sertifikat & Kompetensi": "Certificates & Competency",
  "nilai": "score",
  "Selesaikan kursus di menu Belajar untuk mendapatkan sertifikat. Sertifikat yang terbit otomatis tampil di sini.": "Complete the courses under the Learn menu to earn a certificate. Certificates issued appear here automatically.",
  "Penyimpanan sandi": "Password storage",
  "ber-salt": "salted",
  "teks polos (akun contoh)": "plain text (demo account)",
  "Kata sandi akun ini tersimpan sebagai turunan PBKDF2 ber-salt, bukan teks asli.": "This account's password is stored as a salted PBKDF2 derivation, not as the original text.",
  "Akun contoh ini masih menyimpan sandi apa adanya. Begitu Anda menggantinya lewat kotak di samping, akun ini otomatis naik ke bentuk ber-hash. Pada produksi, seluruh pemeriksaan ini tetap harus pindah ke server — lihat README.": "This demo account still stores its password as-is. As soon as you change it using the box beside this, the account is upgraded to the hashed form automatically. In production, all of these checks must still move to the server — see the README.",
  "Kerjakan pesanan cleaning service, cuci AC, taman, dan lainnya. Wajib mengikuti pelatihan dan sertifikasi kompetensi di aplikasi.": "Take on cleaning, AC servicing, gardening, and other jobs. Training and competency certification in the app are required.",
  "Beralih menjadi Mitra mengubah tampilan aplikasi Anda menjadi aplikasi lapangan. Riwayat pesanan Anda sebagai klien tetap tersimpan.": "Switching to Partner turns your app into a field app. Your order history as a client is kept.",
  "Jual peralatan dan chemical kebersihan Anda sendiri di marketplace EXOCLEAN, dengan sistem bagi hasil.": "Sell your own cleaning equipment and chemicals on the EXOCLEAN marketplace, on a revenue-share basis.",
  "Beralih menjadi Mitra Toko mengubah tampilan aplikasi Anda menjadi ruang kerja penjual.": "Switching to Store Partner turns your app into a seller workspace.",
  "Lengkapi verifikasi dulu.": "Complete verification first.",
  "Satu akun bisa menjalankan lebih dari satu peran. Affiliate dan Dropshipper berjalan berdampingan dengan akun klien Anda.": "One account can hold more than one role. Affiliate and Dropshipper run alongside your client account.",
  "Setelah diajukan, aplikasi Anda berganti menjadi tampilan mitra dan Anda mulai dari langkah bergabung: menyetujui Syarat & Ketentuan, melengkapi berkas, lalu mengikuti pembelajaran wajib.": "Once submitted, your app switches to the partner view and you start from the joining steps: accepting the Terms & Conditions, completing your documents, then taking the required training.",
  "Ya, ajukan": "Yes, apply",
  "Aplikasi Anda akan berganti menjadi ruang kerja penjual. Toko baru tayang setelah profil lengkap dan disetujui admin.": "Your app will switch to a seller workspace. A new store goes live once its profile is complete and an admin approves it.",
  "Kota gudang": "Warehouse city",
  "Kategori utama": "Main category",
  "Tiket undian bukan alat bayar — ia tidak pernah muncul saat checkout. Nilainya baru ada setelah diundi, dan pengundian tidak bisa dibatalkan. Karena itu halamannya sendiri, dan izinnya sendiri.": "A draw ticket is not a payment method — it never appears at checkout. Its value only exists once the draw is run, and a draw cannot be undone. Hence its own page, and its own permission.",
