  "Penjualan tiket ditutup.": "Ticket sales closed.",
  "Tiketnya TETAP ada dan tetap bisa diundi lewat riwayat, tetapi undian ini tidak akan bisa dijalankan lagi setelah dihapus. Pertimbangkan menutup penjualannya saja.": "The tickets REMAIN and can still be drawn from the history, but this draw can never be run again once deleted. Consider just closing its sales instead.",
  "Undian dihapus.": "Draw deleted.",
  "Tiket undian dijual seperti voucher, tetapi tidak pernah memotong tagihan. Bila nilai hadiah uang diisi, hadiah langsung masuk Dompet pemenang saat diundi.": "Draw tickets are sold like vouchers, but never reduce a bill. If a cash prize value is entered, the prize goes straight into the winner's Wallet when drawn.",
  "mis. Undian Akhir Tahun 2026": "e.g. End of Year Draw 2026",
