  "orang": "people",
  "Seluruh tiket peserta ikut tercatat bersama hasilnya, bukan hanya pemenangnya — sehingga keadilan pengundian bisa ditelusuri kapan pun ada yang bertanya.": "Every entrant's ticket is recorded with the result, not just the winners' — so the fairness of the draw can be traced whenever anyone asks.",
  "Satu orang bisa menang lebih dari sekali bila punya beberapa tiket — itu memang konsekuensi membeli lebih banyak tiket.": "One person can win more than once if they hold several tickets — that is simply the consequence of buying more tickets.",
  "Pemberitahuan WhatsApp untuk tiap pemenang sudah disiapkan di Outbox.": "A WhatsApp notification for each winner has been prepared in the Outbox.",
