  "Voucher hadiah dikirim beserta kodenya — penerima cukup memasukkan kode itu di menu Voucher, dan tidak perlu sudah punya akun saat Anda membelinya.": "A gift voucher is sent with its code — the recipient just enters that code under the Vouchers menu, and does not need an account when you buy it.",
  "Klaim": "Claim",
  "Beli tiket di tab Beli Voucher, atau tukarkan poin Anda. Semakin banyak tiket, semakin besar peluang menang.": "Buy tickets under the Buy Vouchers tab, or redeem your points. The more tickets, the better your odds of winning.",
  "undian!": "draws!",
  "Voucher yang Anda belikan untuk orang lain akan muncul di sini beserta status klaimnya.": "Vouchers you buy for other people appear here along with their claim status.",
  "dengan": "with",
  "Beli Sekarang": "Buy Now",
  "cukup. Setelah pembelian sisa": "is enough. After the purchase,",
  "kurang": "short by",
  "Isi saldo lebih dulu lewat menu Dompet — voucher bernilai uang hanya diterbitkan setelah dananya benar-benar ada.": "Top up via the Wallet menu first — cash vouchers are only issued once the money is genuinely there.",
  "Penerima": "Recipient",
  "mis. Selamat ulang tahun! Semoga bermanfaat.": "e.g. Happy birthday! Hope it comes in handy.",
  "Hadiah terkirim 🎁": "Gift sent 🎁",
  "Bila penerimanya belum punya akun, salin kodenya dan kirimkan sendiri — voucher ini melekat pada kode, bukan pada akun.": "If the recipient has no account yet, copy the code and send it yourself — this voucher attaches to the code, not to an account.",
  "Voucher ini akan otomatis muncul sebagai pilihan saat Anda checkout, selama syaratnya terpenuhi.": "This voucher will appear automatically as an option when you check out, as long as its conditions are met.",
  "Jenis, nilai rupiah, persentase beserta batas atasnya, harga jual, harga poin, masa berlaku, kuota, dan di mana voucher boleh dipakai. Ketentuan dibekukan saat voucher terbit — mengubah katalog tidak pernah menyusutkan voucher yang sudah di tangan orang.": "Type, rupiah value, percentage and its cap, selling price, point price, validity, quota, and where the voucher may be used. Terms are frozen when a voucher is issued — changing the catalogue never shrinks a voucher already in someone's hands.",
  "Dibeli": "Bought",
  "sisa kuota": "quota left",
  "voucher": "vouchers",
  "Terbitkan manual": "Issue manually",
  "asal": "origin",
  "Voucher itu TETAP berlaku — ketentuannya sudah dibekukan pada masing-masing voucher. Yang hilang hanya kemampuan menerbitkan yang baru.": "Those vouchers REMAIN valid — their terms were frozen onto each one. All that is lost is the ability to issue new ones.",
  "Pemiliknya tidak akan bisa memakainya lagi. Pakai ini hanya untuk voucher yang terbit karena kekeliruan.": "The owner will no longer be able to use it. Use this only for vouchers issued by mistake.",
  "Voucher yang diterbitkan di sini tidak dibayar dan tidak menukar poin — ia langsung menjadi beban perusahaan. Tercatat atas nama Anda.": "Vouchers issued here are not paid for and do not consume points — they become a company cost directly. Recorded under your name.",
