  "Kolom yang perlu diisi menyesuaikan jenis voucher. Isi jenisnya lebih dulu, lalu lengkapi kolom yang sesuai — kolom lain boleh dibiarkan nol.": "The fields you need depend on the voucher type. Choose the type first, then fill in the matching fields — the rest may be left at zero.",
