  "Password agen tidak pernah disimpan di sini.": "The agent password is never stored here.",
  "Ia kunci ke saldo deposit perusahaan — tempatnya hanya berkas .env pada server. Yang dikirim ke Darmawisata pun bukan passwordnya, melainkan turunannya yang dihitung ulang setiap login.": "It is the key to the company's deposit balance — its only home is the server's .env file. What is sent to Darmawisata is not the password either, but a derivation recomputed at every login.",
