  "Satu ketukan ganda pada tombol bayar, satu jaringan lambat yang dicoba ulang, atau satu muat ulang halaman di saat yang salah — semuanya membayar tagihan yang sama dua kali. Uangnya nyata dan tidak kembali sendiri.": "A double tap on the pay button, one slow network retried, or one page reload at the wrong moment — each pays the same bill twice. The money is real and does not come back on its own.",
