  "Cek tagihan dulu — nomor referensinya datang dari sana.": "Check the bill first — the reference number comes from there.",
  "Isi nomor tujuan dulu": "Enter the destination number first",
  "Catatan transaksi": "Transaction records",
  "Setiap panggilan yang memotong deposit, beserta nasibnya": "Every call that deducts the deposit, and how it ended",
  "Muat catatan": "Load records",
  "Belum dimuat.": "Not loaded yet.",
  "transaksi berakhir tanpa kepastian.": "transactions ended without certainty.",
  "Cocokkan satu per satu ke riwayat transaksi Darmawisata sebelum dicoba lagi. Selama belum dicocokkan, aplikasi menolak mengulangnya — dan itu memang yang seharusnya.": "Reconcile each one against Darmawisata's transaction history before retrying. Until reconciled, the app refuses to repeat them — and that is exactly right.",
  "Belum ada transaksi yang memotong deposit.": "No deposit-deducting transactions yet.",
  "Keadaan": "State",
  "Sebab": "Reason",
  "Bagaimana pembayaran ganda dicegah": "How double payment is prevented",
  "Setiap permintaan uang membawa kunci yang diturunkan dari MAKSUDNYA — nomor referensi tagihan untuk PPOB, gabungan nomor dan produk untuk TopUp — bukan angka acak per klik. Dua ketukan pada tagihan yang sama menghasilkan kunci yang sama, dan yang kedua tidak pernah sampai ke Darmawisata.": "Every money request carries a key derived from its INTENT — the bill reference for PPOB, the number plus product for TopUp — not a random value per click. Two taps on the same bill produce the same key, and the second never reaches Darmawisata.",
  "Yang paling penting justru keadaan ketiga: panggilan yang putus sebelum ada jawaban. Uang mungkin sudah keluar, mungkin belum, dan tidak ada cara mengetahuinya dari sisi kita. Transaksi seperti itu ditandai ragu dan tidak pernah diulang otomatis — mengulang sesuatu yang mungkin sudah berhasil persis sama dengan membayar dua kali.": "The third state matters most: a call that drops before any reply. The money may have moved, or may not, and there is no way to tell from our side. Such transactions are marked uncertain and are never retried automatically — retrying something that may already have succeeded is exactly the same as paying twice.",
  "Membaca catatan…": "Reading records…",

  "Waktu mulai": "Started",

