  "Belum ada ulasan": "No reviews yet",
  "Ulasan hanya bisa ditulis oleh pembeli yang barangnya sudah diterima — jadi yang tampil di sini selalu dari orang yang benar-benar memakainya.": "Reviews can only be written by buyers whose goods have arrived — so what appears here always comes from someone who actually used it.",
