  "Ceritakan singkat — kualitas, kemasan, kesesuaian dengan keterangannya. Boleh dikosongkan.": "Say a little — quality, packaging, whether it matched the description. May be left empty.",
  "barang menunggu diulas": "items awaiting a review",
  "Ulasan Anda tampil di halaman produk dan memengaruhi urutan katalog. Yang jujur lebih berguna daripada yang murah hati.": "Your review appears on the product page and affects catalogue ordering. An honest one is more useful than a generous one.",
