  "Ganti rugi berlaku untuk paket yang hilang atau rusak dalam perjalanan, dibuktikan dengan berita acara kurir.": "Compensation applies to parcels lost or damaged in transit, evidenced by the courier's report.",
  "Tidak menanggung kerusakan akibat pengemasan yang tidak sesuai ketentuan kurir, barang terlarang, dan barang yang salah alamat karena alamat yang keliru diisi pembeli.": "It does not cover damage from packaging that breaches courier rules, prohibited goods, or misdelivery caused by an address the buyer entered incorrectly.",
