  "Dari permintaan klien, penawaran harga, penjadwalan tim, absensi GPS di lapangan, verifikasi mutu, sampai invoice dan penilaian — semuanya terhubung dalam satu alur.": "From client requests, quotes, crew scheduling and GPS attendance in the field, through quality checks, to invoices and ratings — all connected in one flow.",
