  "{n} layanan di “{k}” akan berhenti ditawarkan untuk pemesanan baru. Pekerjaan yang sedang berjalan tidak terpengaruh.": "{n} services in “{k}” will stop being offered for new bookings. Work already under way is unaffected.",
  "Peran “{v}” akan dihapus permanen.": "The “{v}” role will be deleted permanently.",
  "<b>Yang perlu Anda tahu sebelum mendaftar.</b> Setelah akun dibuat, Anda akan diminta menyetujui Syarat &amp; Ketentuan Mitra, melengkapi berkas identitas, lalu <b>mengikuti pembelajaran wajib di aplikasi</b>. Penugasan baru bisa Anda terima setelah seluruh kursus wajib lulus (nilai minimal {kkm}) dan berkas Anda disetujui admin. Pendaftaran <b>tidak dipungut biaya apa pun</b>.": "<b>What to know before you apply.</b> Once your account exists you will be asked to accept the Partner Terms, upload identity documents, and then <b>complete the required training in the app</b>. You can only receive assignments after passing every required course (minimum score {kkm}) and having your documents approved by an admin. Applying is <b>completely free</b>.",
