  "Barang pada pesanan <b>{no}</b> sedang habis stok ({habis}) atau sudah ditarik dari katalog ({hilang}).": "Items in order <b>{no}</b> are out of stock ({habis}) or withdrawn from the catalogue ({hilang}).",
  "Biaya dipotong dari <b>saldo iklan</b> Anda ({v}). Iklan berhenti otomatis bila anggaran atau saldo habis.": "Charges come out of your <b>ad balance</b> ({v}). Ads stop automatically when the budget or the balance runs out.",
