  "Undian": "Raffle",
  "Belum ada <b>foto sesudah</b>. Foto ini dipakai supervisor dan klien untuk menilai hasil kerja.": "No <b>after photo</b> yet. Supervisors and clients use it to judge the finished work.",
  "Terima permintaan, absen di lokasi, laporkan hasil dengan foto, dan pantau pendapatan Anda — tanpa berpindah aplikasi.": "Accept jobs, clock in on site, report results with photos, and track your earnings — without leaving the app.",
  "Daftarkan area, susun jadwal berulang, ingatkan petugas otomatis, dan terima bukti foto sebelum–sesudah untuk setiap langkah.": "Register areas, set recurring schedules, remind attendants automatically, and receive before-and-after photo proof for every step.",
  "Bertukar nomor memindahkan percakapan ke luar aplikasi — di sana tidak ada rekaman, tidak ada perlindungan bagi hasil, dan tidak ada bukti bila terjadi sengketa. Pegawai internal dikecualikan.": "Swapping phone numbers moves the conversation outside the app — where there is no record, no revenue-share protection, and no evidence if a dispute arises. Internal staff are exempt.",
  "Inspeksi menyatakan bersih, penghuni tidak. Yang diperiksa mungkin bukan yang mereka rasakan — bau, jam pembersihan, atau ruangan yang tidak masuk daftar inspeksi.": "The inspections say clean, the occupants do not. What is being checked may not be what they experience — smell, the hour it is cleaned, or rooms that are not on the inspection list.",
  "Penghuni puas, inspeksi tidak. Standar inspeksi mungkin lebih ketat daripada yang dituntut pemakai ruangan — itu belum tentu salah, tetapi layak ditanyakan.": "The occupants are satisfied, the inspections are not. The inspection standard may be stricter than the people using the rooms require — not necessarily wrong, but worth asking about.",
