  "Perbuatan penting dicatat beserta nama, waktu, dan perangkatnya: masuk dan keluar, penggantian kata sandi, aduan yang Anda kirim, dan penilaian yang Anda beri.": "Important actions are recorded with your name, the time, and the device: signing in and out, password changes, the reports you send, and the ratings you give.",
  "Aduan dan penilaian Anda tercatat bernama": "Your reports and ratings are recorded under your name",
  "Aduan dan penilaian yang Anda kirim menyebut nama Anda, dan bisa dibaca staf kebersihan serta atasan mereka. Itu disengaja: aduan bernama bisa ditanyakan balik dan bisa dikabari hasilnya.": "The reports and ratings you send carry your name, and can be read by the cleaning staff and their supervisors. That is deliberate: a named report can be asked about and can be answered.",
  "Bila Anda lebih suka tidak menyebut nama, pakailah tag QR yang tertempel di ruangan. Aduan lewat tag tetap tanpa nama, dan tetap ditangani.": "If you would rather not give your name, use the QR tag on the wall. Reports through the tag stay anonymous, and are still acted on.",
  "Penilaian Anda menilai KEADAAN RUANGAN, bukan orangnya. Ia tidak dipakai sebagai nilai kinerja petugas kebersihan mana pun.": "Your rating rates THE STATE OF THE ROOM, not the person. It is not used as any attendant’s performance score.",
  "Mengirim aduan yang Anda tahu tidak benar, atau menilai ruangan yang tidak pernah Anda lihat hari itu.": "Sending a report you know to be untrue, or rating a room you did not see that day.",
  "Memakai penilaian untuk menekan petugas tertentu. Bila ada masalah dengan seseorang, sampaikan kepada penyelianya — bukan lewat angka yang tidak bisa ia bantah.": "Using ratings to pressure a particular attendant. If you have a problem with someone, tell their supervisor — not through a number they cannot answer back.",
  "Mencoba membuka ruangan orang lain atau menembus pembatasan hak akses.": "Trying to open someone else’s rooms or to get past the access limits.",
  "{n} liter/bulan": "{n} liters/month",

