  "Penyimpanan bersama menyala.": "Shared storage is on.",
  "Data disimpan di basis data pada server, bukan di browser ini. Perangkat lain yang menyambung ke server yang sama melihat data yang sama.": "Data lives in a database on the server, not in this browser. Any device connected to the same server sees the same data.",
  "Sekarang luring": "Currently offline",
  "perubahan Anda ditahan dan dikirim begitu server terjangkau lagi.": "your changes are held and sent as soon as the server is reachable again.",
  "Data masih di browser ini saja.": "Data is still only in this browser.",
  "Ia hilang bila penyimpanan browser dibersihkan, dan tidak bisa dibuka dari perangkat lain. Nyalakan penyimpanan bersama di bawah untuk memindahkannya ke basis data di server.": "It disappears if browser storage is cleared, and cannot be opened from another device. Turn on shared storage below to move it into a database on the server.",
  "Menghubungi server…": "Contacting the server…",
  "Server tidak menjawab": "The server did not answer",
  "baris di server": "rows on the server",
  "Pindahkan seluruh data ke server?": "Move all data to the server?",
  "Seluruh isi penyimpanan browser ini disalin ke basis data di server, dan sejak itu server yang menjadi sumbernya. Lakukan ini dari SATU perangkat saja — perangkat lain cukup disambungkan.": "Everything in this browser’s storage is copied into the database on the server, and from then on the server is the source. Do this from ONE device only — other devices just connect.",
