  "baris tersimpan di server": "rows stored on the server",
  "Aplikasi dimuat ulang…": "Reloading the app…",
  "Ambil data dari server?": "Fetch data from the server?",
  "Data yang sekarang ada di browser ini DIGANTI dengan isi server. Pakai ini pada perangkat kedua dan seterusnya.": "The data currently in this browser is REPLACED by the server’s. Use this on the second device onward.",
  "Ambil dari server": "Fetch from server",
  "Mengambil…": "Fetching…",
  "Terambil. Aplikasi dimuat ulang…": "Fetched. Reloading the app…",
  "Kembali ke penyimpanan browser?": "Back to browser storage?",
  "Aplikasi berhenti mengirim dan mengambil dari server. Salinan yang ada sekarang tetap dipakai di perangkat ini — dan sejak itu ia kembali bisa hilang bila penyimpanan browser dibersihkan.": "The app stops sending to and fetching from the server. The copy you have now stays on this device — and from then on it can disappear again if browser storage is cleared.",
