  "Apa arti angka di atas.": "What the figures above mean.",
  "“Selesai dilaporkan” berarti seseorang menandainya selesai di aplikasi. “Disertai bukti kehadiran” berarti tag area benar-benar dipindai di lokasi. Selisih antara keduanya adalah pekerjaan yang tidak bisa dibuktikan — bukan berarti tidak dikerjakan, tetapi tidak bisa ditunjukkan kepada siapa pun.": "“Reported done” means someone marked it done in the app. “With proof of presence” means the area tag was actually scanned on site. The gap between the two is work that cannot be evidenced — not necessarily undone, but impossible to show anyone.",
