  /* MCS — bukti kehadiran lewat tag QR yang tertempel di area. */
  "Anda terdeteksi {jarak} m dari area ini — terlalu jauh untuk dianggap hadir.": "You were detected {jarak} m from this area — too far to count as present.",
  "Pindai dulu tag di {area}. Laporan tanpa bukti kehadiran hanya pengakuan sendiri.": "Scan the tag at {area} first. A report with no proof of presence is only a self-claim.",
  "Pindai tag": "Scan tag",
  "Pindai tag area": "Scan area tag",
  "Arahkan kamera ke tag yang tertempel di dinding": "Point the camera at the tag on the wall",
  "Peramban ini tidak bisa memindai QR. Ketik kodenya saja — enam huruf yang tercetak di bawah gambar tag.": "This browser cannot scan QR codes. Just type the code — the six characters printed under the tag image.",
  "Menyalakan kamera…": "Starting the camera…",
  "Atau ketik kode tag": "Or type the tag code",
  "Kode yang diketik dicatat berbeda dari kode yang dipindai kamera — keduanya muncul apa adanya di laporan.": "A typed code is recorded differently from a camera-scanned one — both appear as they are in the report.",
  "Arahkan ke tag…": "Point at the tag…",
  "Kamera tidak bisa dipakai": "The camera cannot be used",
  "Ketik kodenya saja.": "Just type the code.",
  "Tag tidak dikenali.": "Tag not recognised.",
  "Itu tag {lain} — yang dibutuhkan tag {ini}.": "That is the {lain} tag — the one needed is {ini}.",
  "Mencatat kehadiran…": "Recording presence…",
  "Kehadiran tercatat di": "Presence recorded at",
  "Tag area": "Area tag",
  "PETUGAS: pindai sebelum mulai membersihkan.": "ATTENDANT: scan before you start cleaning.",
  "PENGHUNI: pindai untuk melaporkan area ini kotor atau rusak.": "OCCUPANT: scan to report this area as dirty or broken.",
  "Tempel di dekat pintu masuk area, setinggi mata, tidak di balik daun pintu. Kode ini melekat pada area dan tidak pernah berubah — cetak sekali, pakai seterusnya.": "Stick it near the area entrance at eye level, not behind the door leaf. This code belongs to the area and never changes — print once, use forever.",
  "dipindai": "scanned",
  "kode diketik": "code typed",
  "Bukti kehadiran": "Proof of presence",
  "Belum dipindai.": "Not scanned yet.",
  "Gedung ini menuntut tag area dipindai sebelum tugas ditandai selesai.": "This building requires the area tag to be scanned before a task can be marked done.",
  "Pindai sekarang": "Scan now",
  "Tag QR yang ditempel di area, dipindai sebelum melapor": "A QR tag stuck in the area, scanned before reporting",
  "Tanpa ini, laporan kebersihan adalah pengakuan sendiri — siapa pun bisa mencentang apa pun dari mana pun. Dengan tag tertempel, laporan menuntut seseorang pernah berada di sana.": "Without this, a cleaning report is a self-claim — anyone can tick anything from anywhere. With a tag on the wall, a report requires that someone was actually there.",
  "Wajib pindai tag sebelum menandai selesai": "Require a tag scan before marking done",
  "Berlaku untuk semua area gedung ini.": "Applies to every area in this building.",
  "1 area belum pernah dipindai sama sekali": "1 area has never been scanned at all",
  "{n} area belum pernah dipindai sama sekali": "{n} areas have never been scanned at all",
  "Pastikan tagnya sudah dicetak dan tertempel, kalau tidak pelaporan di sana akan terkunci: ": "Make sure their tags are printed and stuck up, otherwise reporting there will be locked: ",
  "Pindaian berlaku berapa menit": "A scan stays valid for (minutes)",
  "Sekali pindai menutupi pekerjaan sepanjang rentang ini.": "One scan covers the work done within this window.",
  "Jarak maksimal dari titik area (m)": "Maximum distance from the area point (m)",
  "0 = tidak diperiksa. GPS di dalam gedung meleset puluhan meter, jadi angkanya sengaja longgar.": "0 = not checked. Indoor GPS drifts by tens of metres, so this figure is deliberately loose.",
