  "Skor dihitung dari yang bisa dicatat aplikasi: tugas, pemindaian tag, foto, inspeksi, kehadiran, dan aduan. Ia tidak melihat kesungguhan, kesediaan menolong rekan, keselamatan kerja, maupun mutu pekerjaan yang tidak pernah diinspeksi. Pakailah sebagai bahan percakapan penilaian, bukan penggantinya.": "The score is computed from what the app can record: tasks, tag scans, photos, inspections, attendance and complaints. It does not see diligence, willingness to help a colleague, safety at work, or the quality of work that was never inspected. Use it as material for the review conversation, not as a replacement for it.",
