  "Rata-rata inspeksi APPA di area tanggung jawabnya. 1 terbaik, 5 terburuk — dibalik menjadi skor.": "Average APPA inspection on their assigned areas. 1 best, 5 worst — inverted into a score.",
  "Aduan di areanya": "Complaints on their areas",
  "MATI secara bawaan, dan sebaiknya tetap begitu. Jumlah aduan lebih ditentukan oleh ramainya gedung daripada oleh rajinnya petugas; menyalakannya berarti menghukum orang atas area tempat ia ditugaskan. Tetap ditampilkan sebagai keterangan.": "OFF by default, and best left that way. The number of complaints is driven more by how busy the building is than by how diligent the attendant is; switching it on means penalising someone for the area they were assigned to. Still shown as information.",
  "Capaian regu": "Team achievement",
  "Penyelesaian tugas seluruh anak buahnya, langsung maupun tidak.": "Task completion across all their subordinates, direct and indirect.",
  "Cakupan inspeksi": "Inspection coverage",
  "Area di bawahnya yang ia periksa setidaknya sekali pada periode ini. Penyelia yang tidak pernah menginspeksi tidak sedang menyelia.": "Areas under them that they inspected at least once in this period. A supervisor who never inspects is not supervising.",
