  "Tanggap aduan": "Complaint response",
  "Aduan penghuni di wilayahnya yang tuntas dalam batas waktu.": "Occupant complaints in their zone resolved within the deadline.",
  "Penanganan ketidakhadiran": "Absence handling",
  "Anak buah yang absen dan ADA penggantinya. Absen bukan kesalahan penyelia; membiarkan areanya kosong adalah kesalahannya.": "Absent subordinates who DID have a substitute. An absence is not the supervisor's fault; leaving the area uncovered is.",
