  "Bobot menentukan seberapa besar tiap aspek memengaruhi nilai akhir. Jumlahnya tidak harus 100 — yang dipakai adalah perbandingannya. Beri 0 untuk mematikan sebuah aspek sama sekali.": "Weights decide how much each aspect affects the final score. They need not add up to 100 — what matters is their ratio. Set 0 to switch an aspect off entirely.",
