  "Pekerjaan tambahan berbeda dari jadwal dan dari aduan.": "Extra jobs are different from schedules and from complaints.",
  "Jadwal sudah disepakati dan berulang. Aduan datang dari penghuni dan tidak boleh menunggu persetujuan. Yang di sini DIMINTA, punya biaya, dan sering ditagih terpisah — karena itu ada tahap persetujuannya.": "A schedule is already agreed and repeats. A complaint comes from an occupant and must not wait for anyone's approval. What sits here is REQUESTED, carries a cost, and is often billed separately — which is why there is an approval stage.",
