  /* ---- MCS: keselamatan kerja (K3) ---- */
  "Keselamatan Kerja": "Safety at Work",
  "Kecelakaan, nyaris celaka, dan bahan berbahaya": "Accidents, near misses, and hazardous chemicals",
  "Nyaris celaka": "Near miss",
