  "Kerusakan properti": "Property damage",
  "Hampir terjadi, tidak ada yang cedera. Justru ini yang paling berguna dicatat.": "Almost happened, nobody hurt. This is the most useful kind to record.",
  "Tertangani dengan kotak P3K, petugas tetap bekerja.": "Handled with the first aid kit; the attendant kept working.",
