  "Mudah terbakar": "Flammable",
  "Jangan dicampur dengan pemutih klorin — melepaskan gas beracun.": "Never mix with chlorine bleach — it releases toxic gas.",
  "Jangan dicampur dengan pembersih asam, amonia, atau cuka — melepaskan gas klorin.": "Never mix with acidic cleaners, ammonia or vinegar — it releases chlorine gas.",
  "Jangan dicampur dengan pemutih klorin — melepaskan gas kloramin.": "Never mix with chlorine bleach — it releases chloramine gas.",
  "Jauhkan dari sumber panas dan api.": "Keep away from heat and flame.",
  "Ceritakan kejadiannya — tanpa itu tidak ada yang bisa dipelajari.": "Describe what happened — without it there is nothing to learn from.",
  "Laporan tidak ditemukan.": "Report not found.",
  "Tulis akar masalahnya. \"Sudah dibersihkan\" bukan akar masalah.": "Write the root cause. \"It has been cleaned up\" is not a root cause.",
  "Tulis apa yang diubah supaya tidak terulang.": "Write what was changed so it does not happen again.",
  "Ini catatan internal, bukan laporan resmi.": "This is an internal record, not an official report.",
  "Kewajiban melaporkan kecelakaan kerja punya formulir dan tenggatnya sendiri menurut aturan setempat — di Indonesia antara lain ke BPJS Ketenagakerjaan. Isian di sini cukup untuk mengisi formulir resmi itu, tetapi bukan penggantinya.": "The duty to report workplace accidents has its own forms and deadlines under local law — in Indonesia, to BPJS Ketenagakerjaan among others. What is captured here is enough to fill in that official form, but it is not a substitute for it.",
  "Ada bahan di gudang yang tidak boleh dicampur.": "There are chemicals in the store that must never be mixed.",
  "Hari tanpa cedera": "Days without injury",
  "belum pernah ada laporan cedera": "no injury has ever been reported",
  "dicatat sebelum ada yang cedera": "recorded before anyone got hurt",
