  "Laporkan kejadian": "Report an incident",
  "Laporkan": "Report",
  "Laporkan juga yang NYARIS terjadi. Laporan nyaris celaka tidak menghukum siapa pun — ia satu-satunya cara mencegah kejadian berikutnya sebelum ada yang cedera.": "Report what ALMOST happened too. A near-miss report punishes nobody — it is the only way to prevent the next incident before anyone gets hurt.",
  "Apa yang terjadi": "What happened",
  "Sebabnya": "The cause",
