  "Boleh dikosongkan. Laporan nyaris celaka yang menuntut nama akan berhenti masuk.": "May be left empty. Near-miss reports that demand a name simply stop coming in.",
  "Ceritakan kejadiannya": "Describe what happened",
  "mis. Tanda lantai basah belum dipasang, penghuni hampir jatuh di dekat lift lantai 2.": "e.g. The wet floor sign was not up yet; an occupant nearly slipped near the 2nd floor lift.",
  "Apa yang langsung dilakukan": "What was done right away",
  "Hari kerja yang hilang": "Work days lost",
  "Isi 0 bila petugas tetap bekerja.": "Enter 0 if the attendant kept working.",
  "APD yang sedang dipakai": "PPE being worn",
  "Kosong berarti tidak dicatat, bukan berarti tidak dipakai.": "Empty means not recorded, not that none was worn.",
  "Laporan diperbarui": "Report updated",
  "Laporan tercatat": "Report recorded",
  "Laporan yang ditutup dengan “sudah dibersihkan” tidak mencegah apa pun. Dua pertanyaan ini yang mencegah kejadian berikutnya.": "A report closed with “it has been cleaned up” prevents nothing. These two questions are what prevent the next one.",
  "Kenapa ini terjadi": "Why did this happen",
  "mis. Tanda lantai basah hanya ada dua untuk lima lantai.": "e.g. There are only two wet floor signs for five floors.",
  "Apa yang diubah supaya tidak terulang": "What was changed so it does not recur",
  "mis. Dibelikan enam tanda tambahan; dimasukkan ke langkah wajib pada checklist area basah.": "e.g. Six more signs purchased; added as a required step on the wet-area checklist.",
  "Laporan ditutup.": "Report closed.",
