  "Catatan internal. Kewajiban pelaporan resmi punya formulir dan tenggatnya sendiri menurut aturan setempat.": "Internal record. Official reporting duties have their own forms and deadlines under local law.",
  "Hapus laporan": "Delete report",
  "Catatan keselamatan sebaiknya TIDAK dihapus — pola bahaya baru terbaca setelah puluhan laporan terkumpul. Hapus hanya bila laporannya memang salah masuk.": "Safety records should NOT be deleted — hazard patterns only become readable after dozens of reports accumulate. Delete only if the report was genuinely filed by mistake.",
