  "Kosongkan untuk memakai bawaan jenisnya. Isi 0 bila tidak perlu servis berkala. Buku manual pabrikan lebih tahu daripada bawaan mana pun.": "Leave empty to use the type's default. Enter 0 if it needs no periodic service. The manufacturer's manual knows better than any default.",
  "Hitungan jatuh tempo dimulai dari sini, bukan dari tanggal beli.": "The due-date count starts here, not from the purchase date.",
