  "Sejak diserahkan, peralatan ini tercatat atas nama penerimanya sampai dikembalikan. Itulah satu-satunya cara kehilangan bisa ditelusuri.": "From handover onward this equipment is recorded in the receiver's name until it is returned. That is the only way a loss can be traced.",
