  "Peralatan yang dilepas tidak dihapus — riwayatnya tetap tersimpan. Yang berubah hanya keadaannya, supaya ia keluar dari daftar aktif.": "Retired equipment is not deleted — its history stays. Only its state changes, so it leaves the active list.",
