  "Berhadapan dengan penghuni, menjawab keluhan, etika di area kerja.": "Dealing with occupants, answering complaints, conduct in the work area.",
  "Sertifikat resmi": "Formal certificate",
  "Diterbitkan lembaga di luar gedung dan punya masa berlaku.": "Issued by a body outside the building and carries an expiry date.",
