  "Pelatihan tidak ditemukan.": "Training not found.",
  "Tanggal pelatihan belum diisi.": "The training date is empty.",
  "Tanggalnya di masa depan. Catat setelah pelatihannya berlangsung.": "That date is in the future. Record it after the training has taken place.",
  "Matriks kompetensi": "Competency matrix",
  "Daftar pelatihan": "Training catalogue",
  "Cetak matriks": "Print matrix",
  "Tambah Pelatihan": "Add Training",
  "Catat Kepesertaan": "Record Attendance",
  "Sertifikat yang habis TIDAK mengunci pekerjaan.": "An expired certificate does NOT lock the work.",
  "Mengunci pelaporan karena sertifikat kedaluwarsa berarti gedungnya tidak dibersihkan DAN tidak ada catatannya — dua kerugian, bukan satu. Yang merah di sini adalah daftar kerja untuk yang menjadwalkan pelatihan ulang, bukan larangan bagi petugasnya.": "Locking reporting because a certificate expired means the building goes uncleaned AND unrecorded — two losses, not one. What is red here is a to-do list for whoever schedules refresher training, not a ban on the attendant.",
  "1 kewajiban pelatihan belum terpenuhi": "1 training requirement unmet",
  "{n} kewajiban pelatihan belum terpenuhi": "{n} training requirements unmet",
  "1 sertifikat habis dalam {h} hari": "1 certificate expires within {h} days",
  "{n} sertifikat habis dalam {h} hari": "{n} certificates expire within {h} days",
  "Jenis pelatihan": "Training types",
  "Kepesertaan tercatat": "Attendance recorded",
  "Pemenuhan rata-rata": "Average fulfilment",
  "dari yang diwajibkan menurut jabatan": "of what the job title requires",
  "Orang belum lengkap": "People not yet complete",
  "Belum ada jenis pelatihan": "No training types yet",
  "Daftarkan dulu jenis pelatihannya — induksi, penanganan bahan kimia, kerja di ketinggian — baru catat siapa yang sudah ikut.": "Register the training types first — induction, chemical handling, working at height — then record who has attended.",
  "Induksi gedung, penanganan bahan kimia, kerja di ketinggian, pemakaian mesin poles.": "Building induction, chemical handling, working at height, operating a floor polisher.",
  "Merah berarti wajib tetapi belum ada atau sudah habis": "Red means required but not held or already expired",
  "Penuhi": "Met",
  "Tidak diwajibkan untuk jabatan ini": "Not required for this job title",
  "diikuti": "attended",
  "tidak diwajibkan": "not required",
  "tanpa masa berlaku": "no expiry",
