  "{n} peserta tercatat": "{n} attendances recorded",
  "wajib bagi": "required for",
  "tidak diwajibkan bagi jabatan mana pun": "not required for any job title",
  "Ubah pelatihan": "Edit training",
  "Tambah jenis pelatihan": "Add a training type",
  "Nama pelatihan": "Training name",
  "mis. Penanganan bahan kimia pembersih": "e.g. Handling cleaning chemicals",
