  "Masa berlaku (bulan)": "Valid for (months)",
  "Isi 0 bila tidak kedaluwarsa. Induksi gedung tidak kedaluwarsa; sertifikat kerja di ketinggian jelas kedaluwarsa.": "Enter 0 if it does not expire. Building induction does not expire; a working-at-height certificate certainly does.",
  "Wajib bagi jabatan": "Required for job titles",
  "Kosongkan bila pelatihan ini baik dipunyai tetapi tidak dituntut. Yang tidak dituntut tidak akan muncul sebagai kekurangan.": "Leave empty if this training is good to have but not demanded. What is not demanded will not show up as a shortfall.",
  "Pelatihan diperbarui": "Training updated",
  "Pelatihan ditambahkan": "Training added",
  "Daftarkan jenis pelatihannya dulu.": "Register the training types first.",
  "Catat kepesertaan": "Record attendance",
  "Pelatihan": "Training",
  "Tanggal mengikuti": "Date attended",
  "Masa berlakunya dihitung dari tanggal ini.": "The validity period counts from this date.",
  "Dinyatakan lulus": "Declared passed",
  "Yang tidak lulus tetap dicatat — riwayat mengulang itu berguna, dan menghapusnya membuat pelatihan terlihat selalu berhasil.": "A failure is still recorded — the history of retaking is useful, and deleting it makes training look as if it always works.",
  "Nilai (opsional)": "Score (optional)",
