  "Kepesertaan tercatat.": "Attendance recorded.",
  "Belum pernah tercatat mengikuti pelatihan ini.": "Never recorded as attending this training.",
  "Catatan dihapus.": "Record deleted.",
  "Matriks Kompetensi Petugas": "Attendant Competency Matrix",
  "Wajib menurut jabatan · B = berlaku, S = segera habis, H = kedaluwarsa, — = belum ada, · = tidak diwajibkan": "Required by job title · B = valid, S = expiring soon, H = expired, — = not held, · = not required",
  "Sertifikat yang kedaluwarsa tidak mengunci pekerjaan di aplikasi — daftar ini untuk yang menjadwalkan pelatihan ulang.": "An expired certificate does not lock work in the app — this list is for whoever schedules refresher training.",
  "Hapus pelatihan": "Delete training",
  "1 catatan kepesertaan ikut terhapus": "1 attendance record is deleted with it",
