  /* ---- MCS: kontrak & janji layanan ---- */
  "Janji layanan yang bisa diukur, diperiksa tiap bulan": "Measurable service promises, checked every month",
  "Persentase tugas terjadwal yang ditandai selesai.": "The percentage of scheduled tasks marked done.",
  "Dari tugas yang selesai, berapa persen disertai pemindaian tag di lokasi.": "Of the tasks completed, what percentage came with a tag scan on site.",
  "Mutu APPA": "APPA quality",
  "Rata-rata nilai inspeksi. Makin KECIL makin baik — 1 paling bersih.": "The average inspection score. LOWER is better — 1 is cleanest.",
  "Jumlah inspeksi": "Inspection count",
  "Berapa kali minimal area diperiksa dalam sebulan.": "The minimum number of times areas are inspected in a month.",
  "Aduan tepat waktu": "Complaints on time",
  "Dari aduan yang tuntas, berapa persen selesai dalam batas waktunya.": "Of the complaints resolved, what percentage finished within their deadline.",
  "Belum berlaku. Tidak ikut diperiksa.": "Not in force. Not checked.",
  "Berlaku dan diperiksa tiap bulan.": "In force and checked every month.",
  "Masa berlakunya habis atau diakhiri.": "Its term has expired or was ended.",
  "Nama kontrak belum diisi.": "The contract name is empty.",
  "Tanggal mulai belum diisi.": "The start date is empty.",
  "Tanggal berakhir mendahului tanggal mulai.": "The end date comes before the start date.",
  "Kontrak tidak ditemukan.": "Contract not found.",
  "Ini ringkasan terukur dari kontrak, bukan kontraknya.": "This is a measurable summary of the contract, not the contract itself.",
  "Tidak ada penyuntingan pasal, riwayat versi, coretan, atau tanda tangan elektronik yang sah secara hukum. Berkas aslinya tetap harus disimpan di tempat lain. Yang ada di sini adalah janji dalam bentuk angka — supaya bisa diperiksa sendiri tiap bulan, bukan dirakit tangan.": "There is no clause editing, version history, redlining, or legally valid electronic signature here. The original document must still be kept elsewhere. What lives here are the promises expressed as numbers — so they can check themselves every month rather than being assembled by hand.",
  "1 kontrak sudah lewat masa berlakunya": "1 contract is past its term",
  "{n} kontrak sudah lewat masa berlakunya": "{n} contracts are past their term",
  "Jasanya berjalan tanpa dasar tertulis. Perpanjang, atau ubah statusnya menjadi berakhir.": "The service is running with nothing in writing behind it. Renew it, or set its status to ended.",
  "1 kontrak berakhir dalam {h} hari": "1 contract ends within {h} days",
  "{n} kontrak berakhir dalam {h} hari": "{n} contracts end within {h} days",
  "Kontrak berjalan": "Active contracts",
  "1 draf": "1 draft",
  "{n} draf": "{n} drafts",
  "Nilai bulanan": "Monthly value",
  "jumlah kontrak yang berjalan": "total of the active contracts",
  "Janji tidak tercapai": "Promises not met",
  "Segera berakhir": "Ending soon",
  "dalam": "within",
  "1 kontrak": "1 contract",
  "{n} kontrak": "{n} contracts",
  "Kontrak Baru": "New Contract",
  "Belum ada kontrak tercatat": "No contracts recorded yet",
  "Catat janji yang bisa diukur — capaian, bukti, mutu, inspeksi, tanggap aduan — lalu MCS memeriksanya sendiri tiap bulan.": "Record the measurable promises — completion, evidence, quality, inspections, complaint response — and MCS checks them itself every month.",
  "tanpa batas": "no end date",
  "sudah lewat": "overdue by",
  "berakhir dalam": "ends in",
  "belum ada data": "no data yet",
