  "Pihak": "Parties",
  "Masa berlaku": "Term",
  "Lingkup pekerjaan": "Scope of work",
  "Sanksi bila tidak tercapai": "Penalty if not met",
  "Cetak kepatuhan": "Print compliance",
  "Belum ada janji terukur pada kontrak ini. Tambahkan lewat Ubah supaya MCS bisa memeriksanya sendiri tiap bulan.": "No measurable promises on this contract yet. Add them via Edit so MCS can check them itself each month.",
  "Janji bulan ini": "This month's promises",
  "nyata": "actual",
  "Belum ada datanya bulan ini — tidak dihitung gagal, dan tidak dihitung tercapai.": "No data this month — counted neither as failed nor as met.",
  "Ubah kontrak": "Edit contract",
  "Kontrak baru": "New contract",
  "Nama kontrak": "Contract name",
  "mis. Jasa kebersihan Menara A 2026": "e.g. Menara A cleaning services 2026",
