  "Kosongkan untuk dinomori otomatis.": "Leave empty to be numbered automatically.",
  "Pihak dalam kontrak": "Parties to the contract",
  "mis. PT Menara Cakrawala — PT Bersih Sentosa": "e.g. PT Menara Cakrawala — PT Bersih Sentosa",
