  "Kosongkan bila tanpa batas waktu.": "Leave empty if there is no end date.",
  "Nilai per bulan": "Value per month",
  "Hanya yang berjalan yang diperiksa tiap bulan.": "Only active contracts are checked each month.",
  "Kosongkan seluruhnya berarti seluruh gedung": "Leaving everything unticked means the whole building",
  "Uraian lingkup pekerjaan": "Scope of work description",
  "Yang tidak bisa diukur angka ditulis di sini — bukan dijadikan janji terukur. Satu centang hijau tanpa dasar membuat seluruh daftar tidak bisa dipercaya.": "Anything that cannot be measured numerically goes here — not into the measurable promises. One green tick with nothing behind it makes the whole list untrustworthy.",
  "Janji yang bisa diukur": "Measurable promises",
