  "target maksimum": "maximum target",
  "target minimum": "minimum target",
  "mis. potongan 5% dari nilai bulan berjalan": "e.g. 5% deduction from the current month's value",
  "Kontrak diperbarui": "Contract updated",
  "Kontrak dicatat": "Contract recorded",
  "Laporan kepatuhan kontrak": "Contract compliance report",
  "Laporan Kepatuhan Kontrak": "Contract Compliance Report",
  "Kontrak": "Contract",
  "Janji": "Promise",
  "Target": "Target",
