  "Sudah mencapai batas 4 foto.": "The limit of 4 photos has been reached.",
  "Badan mesin, pelat nomor seri, dan kerusakan yang sudah ada saat diterima. Tanpa foto serah terima, setiap lecet menjadi perdebatan tanpa bukti.": "The machine body, the serial plate, and any damage already present on handover. Without a handover photo, every scratch becomes an argument with no evidence.",
  "Masa manfaat ekonomis": "Useful economic life",
  "mis. 5": "e.g. 5",
  "Tahun": "Years",
  "Berapa lama alat ini diperkirakan masih layak dipakai. Dipakai untuk menghitung nilai buku dan kapan penggantinya perlu dianggarkan — bukan perhitungan pajak. Kosongkan untuk memakai bawaan jenisnya.": "How long this item is expected to stay serviceable. Used to compute book value and when a replacement needs budgeting — not a tax calculation. Leave empty to use the default for its type.",
