  "Struktur Tempat": "Place Structure",
  "Lokasi, area, bangunan, lantai, ruangan, dan objeknya": "Sites, areas, buildings, floors, rooms, and their objects",
  "Belum ada lokasi": "No sites yet",
  "Mulai dengan mendaftarkan satu lokasi — gedung, kompleks, atau kantor yang Anda tangani. Areanya menyusul di dalamnya.": "Start by registering one site — the building, complex, or office you look after. Its areas follow inside it.",
  "Lokasi › Area › Bangunan › Lantai › Ruangan › Objek.": "Site › Area › Building › Floor › Room › Object.",
  "Area adalah petak tanah di dalam lokasi — di atasnya boleh berdiri bangunan, boleh tidak. Taman, jalan, dan parkir adalah area tanpa bangunan, dan objeknya menempel langsung di sana. Tingkat yang tidak Anda pakai tidak akan ditampilkan.": "An area is a plot of ground within the site — a building may stand on it, or not. Gardens, driveways, and parking are areas without buildings, and their objects attach directly there. Levels you do not use are not shown.",
