  "Urutannya dari bawah ke atas: basement lebih dulu, rooftop terakhir. Lantai yang namanya tidak berubah tetap membawa ruangannya; lantai yang dihapus melepaskan ruangannya menjadi area, bukan menghapusnya.": "Ordered bottom to top: basements first, rooftop last. A floor whose name is unchanged keeps its rooms; a floor that is removed releases its rooms into areas rather than deleting them.",
  "Buat sekaligus": "Generate them all",
  "Isi jumlahnya, daftarnya dibuatkan. Sunting sesudahnya sebelum disimpan.": "Enter how many and the list is built for you. Edit it before saving.",
