  "Isi bila ada beberapa yang sejenis — \"Meja rapat\", \"Meja resepsionis\".": "Fill this in when there are several of a kind — \"Meeting table\", \"Reception desk\".",
  "Bawaannya tidak. Objek dicentang dari daftar setelah ruangannya dipindai — menempel tag di tiap objek berarti ratusan stiker per gedung dan dua puluh pemindaian per ruangan.": "Off by default. Objects are ticked off a list once the room is scanned — putting a tag on every object means hundreds of stickers per building and twenty scans per room.",
  "Lantainya ikut terhapus. Ruangannya TIDAK — ia dilepaskan menjadi area di bawah lokasi yang sama, beserta seluruh jadwal, tugas, dan foto buktinya.": "Its floors are deleted with it. Its rooms are NOT — they are released into areas under the same site, along with every schedule, task, and photo of evidence.",
