  "Pengguna tidak ditemukan.": "User not found.",
  "Untuk apa aplikasi ini": "What this app is for",
  "MCS EXOCLEAN dipakai mengelola kebersihan gedung: mendaftarkan area dan objek, menyusun jadwal, mencatat kehadiran petugas, memantau mutu, mengelola bahan habis pakai, dan menyusun biaya.": "MCS EXOCLEAN is used to manage building cleaning: registering areas and objects, building schedules, recording attendant attendance, monitoring quality, managing consumables, and working out cost.",
  "Angka biaya yang ditampilkan adalah biaya OPERASIONAL, bukan biaya penuh, dan sebagian angka lain adalah perkiraan yang disebut perkiraan di layarnya. Keputusan yang memakai angka itu tetap keputusan Anda.": "The cost figures shown are OPERATIONAL cost, not full cost, and some other figures are estimates, said to be estimates on the screen itself. Decisions taken on those figures remain your decisions.",
  "Akun ini milik Anda sendiri": "This account is yours alone",
  "Satu akun untuk satu orang. Jangan dipakai bergantian, dan jangan diberikan kepada rekan kerja — seluruh catatan di aplikasi ini menyebut nama pemilik akun, dan catatan yang salah nama tidak bisa diperbaiki kemudian.": "One account, one person. Do not take turns with it, and do not hand it to a colleague — every record in this app names the account holder, and a record under the wrong name cannot be put right afterwards.",
  "Kata sandi sementara dari staf EXOCLEAN wajib diganti pada pemakaian pertama. Sandi yang diketahui dua orang tidak melindungi siapa pun.": "The temporary password from EXOCLEAN staff must be changed on first use. A password two people know protects nobody.",
  "Bila Anda menduga akun Anda dipakai orang lain, ganti kata sandi sekarang juga dan beri tahu penyelia Anda.": "If you suspect someone else is using your account, change the password right now and tell your supervisor.",
  "PIN transaksi": "Transaction PIN",
  "PIN enam angka dipakai menyetujui perbuatan yang memasukkan atau mengeluarkan data dalam jumlah besar: impor berkas CSV, unduhan data, dan penyesuaian stok hasil opname.": "A six-digit PIN is used to approve actions that bring in or take out data in bulk: CSV file imports, data downloads, and stock adjustments from a stocktake.",
  "PIN berbeda dari kata sandi dan tidak pernah ditanyakan lewat telepon, WhatsApp, maupun surel oleh siapa pun — termasuk yang mengaku staf EXOCLEAN.": "The PIN is different from your password and will never be asked for by phone, WhatsApp, or email by anyone — including anyone claiming to be EXOCLEAN staff.",
  "PIN yang salah beberapa kali berturut-turut akan mengunci sementara. Itu disengaja.": "Several wrong PINs in a row will lock it temporarily. That is deliberate.",
  "Data penghuni, petugas, dan foto": "Occupant data, attendant data, and photos",
  "Aplikasi ini menyimpan nama, nomor telepon, kehadiran, dan foto bukti kerja. Sebagian di antaranya data pribadi orang lain yang dipercayakan kepada Anda karena pekerjaan Anda.": "This app stores names, phone numbers, attendance, and photographic evidence of work. Some of it is other people's personal data, entrusted to you because of your job.",
  "Pakailah sebatas keperluan pengelolaan kebersihan gedung. Jangan menyalin, mengunduh, atau meneruskannya untuk keperluan lain, dan jangan menyebarkannya kepada pihak yang tidak berkepentingan.": "Use it only as far as managing the building's cleaning requires. Do not copy, download, or pass it on for any other purpose, and do not share it with anyone who has no business with it.",
  "Foto bukti kerja sering memuat wajah orang. Perlakukan seperti dokumen, bukan seperti gambar biasa.": "Photographic evidence of work often contains people's faces. Treat it as a document, not as an ordinary picture.",
  "Yang tidak boleh dilakukan": "What you must not do",
  "Memasukkan data yang Anda tahu tidak benar — kehadiran fiktif, tugas yang ditandai selesai padahal belum, atau opname yang tidak dihitung.": "Entering data you know to be untrue — attendance that did not happen, tasks marked done that were not, or a stocktake that was never counted.",
  "Mencoba membuka data korporat lain, menembus pembatasan hak akses, atau memakai cara otomatis untuk mengeruk isi aplikasi.": "Trying to open another company's data, getting past access restrictions, or using automated means to scrape the app's contents.",
  "Memakai aplikasi ini untuk hal di luar pengelolaan kebersihan gedung yang menjadi tanggung jawab Anda.": "Using this app for anything beyond managing the cleaning of the building you are responsible for.",
  "Catatan aktivitas": "Activity log",
  "Perbuatan penting dicatat beserta nama, waktu, dan perangkatnya: masuk dan keluar, penggantian sandi dan PIN, impor, unduhan, opname, serta pembacaan percakapan orang lain.": "Important actions are logged with the name, time, and device: signing in and out, password and PIN changes, imports, downloads, stocktakes, and reading other people's conversations.",
  "Catatan itu ada untuk melindungi Anda maupun perusahaan bila kelak ada yang dipertanyakan.": "That log exists to protect you as much as the company if anything is ever questioned.",
  "Penghentian akses": "Ending access",
  "Akses dapat dihentikan bila Anda berhenti bekerja pada gedung ini, atau bila syarat ini dilanggar. Data yang sudah Anda masukkan tetap menjadi milik korporat pemilik gedung dan tidak ikut terhapus.": "Access may be ended if you stop working at this building, or if these terms are broken. Data you have entered remains the property of the company that owns the building and is not deleted with your access.",
  "Perubahan syarat": "Changes to these terms",
  "Bila syarat ini berubah, aplikasi akan meminta persetujuan Anda sekali lagi sebelum bisa dipakai. Yang tercatat adalah versi yang Anda setujui beserta waktunya, bukan sekadar bahwa Anda pernah setuju.": "If these terms change, the app will ask you to accept them once more before it can be used. What is recorded is the version you accepted and when, not merely that you once accepted.",
  "Naskah Bahasa Indonesia adalah naskah yang mengikat. Terjemahan disediakan agar isinya bisa dibaca, bukan untuk menggantikannya.": "The Indonesian text is the binding one. The translation is provided so the content can be read, not to replace it.",
  "Naskah ini mengatur pemakaian aplikasi dan bukan nasihat hukum. Sebelum dipakai pada pelanggan sungguhan, periksakan isinya kepada penasihat hukum perusahaan Anda.": "This text governs use of the app and is not legal advice. Before it is used with real customers, have your own company's legal adviser review it.",
