  "PIN harus 6 angka": "A PIN must be 6 digits",
  "PIN enam angka dipakai menyetujui perbuatan yang mengubah banyak data sekaligus: impor berkas CSV dan penyesuaian stok hasil opname.": "A six-digit PIN is used to approve actions that change a lot of data at once: CSV file imports and stock adjustments from a stocktake.",
  "Enam angka, dipakai menyetujui impor berkas dan penyesuaian stok hasil opname. Berbeda dari kata sandi, dan tidak pernah ditanyakan siapa pun lewat telepon atau WhatsApp.": "Six digits, used to approve file imports and stock adjustments from a stocktake. It is different from your password, and nobody will ever ask for it by phone or WhatsApp.",
  "PIN untuk mengimpor berkas": "PIN to import a file",
  "Impor mengubah ratusan baris sekaligus dan tidak bisa dibatalkan.": "An import changes hundreds of rows at once and cannot be undone.",
  "PIN untuk menyimpan opname": "PIN to save the stocktake",
  "Opname menyesuaikan saldo gudang menurut hitungan fisik Anda.": "A stocktake adjusts the store balance to your physical count.",
  "PIN terkunci. Coba lagi dalam {n} menit.": "PIN locked. Try again in {n} minutes.",
  "PIN salah {n} kali. PIN dikunci {m} menit demi keamanan.": "Wrong PIN {n} times. The PIN is locked for {m} minutes for safety.",
  "PIN salah. Sisa {n} percobaan sebelum terkunci.": "Wrong PIN. {n} attempts left before it locks.",
  "Titik di peta": "Point on the map",
  "Alamat tertulis tidak cukup untuk perusahaan berjaringan — “Jl. Ahmad Yani No. 45” ada di puluhan kota. Titik ini yang dipakai membuka rute di ponsel petugas.": "A written address is not enough for a company with branches — “Jl. Ahmad Yani No. 45” exists in dozens of cities. This point is what opens the route on an attendant’s phone.",
  "peta": "map",
  "titik belum ditandai": "no point marked yet",
  "Peran ini hanya untuk staf korporat.": "This role is for corporate staff only.",
  "Peran tidak dikenal.": "Unknown role.",
  "Ini satu-satunya Admin Korporat yang tersisa. Angkat orang lain lebih dulu.": "This is the only Corporate Admin left. Promote someone else first.",
  "Peran {p} hanya boleh melihat, tidak mengubah.": "The {p} role may only look, not change.",
