  "Nama staf belum diisi.": "The staff name is empty.",
  "Email staf belum diisi.": "The staff email is empty.",
  "Staf korporat tidak ditemukan.": "Corporate staff member not found.",
  "Satu orang, satu peran, dan cabang yang menjadi urusannya.": "One person, one role, and the branches that are their business.",
  "Peran menentukan MENU apa yang terbuka; daftar cabang menentukan DATA siapa yang terlihat. Keduanya perlu — kepala cabang yang boleh membuka Penggajian tanpa batas cabang akan melihat gaji seluruh Indonesia.": "The role decides which MENUS open; the branch list decides whose DATA is visible. Both are needed — a branch manager allowed into Payroll without a branch limit would see wages for the whole country.",
  "Ini pembatasan tampilan, bukan penjagaan server.": "This restricts what is shown, it is not server-side protection.",
  "Aplikasi ini seluruhnya berjalan di peramban, jadi orang yang paham teknis masih bisa membaca data lewat alat pengembang. Pengaturan di sini mencegah orang tersandung ke tempat yang bukan urusannya — ia bukan kunci terhadap yang memang berniat menembus.": "This app runs entirely in the browser, so someone technical can still read the data through developer tools. What you set here stops people wandering into places that are not their business — it is not a lock against anyone determined to get through.",
  "Staf baru": "New staff member",
  "Peran yang tersedia": "Roles available",
  "Apa yang terbuka untuk masing-masing": "What each one opens",
  "semua cabang": "all branches",
  "cabang tertentu": "selected branches",
  "baca saja": "read only",
  "Staf korporat": "Corporate staff",
  "Cabang": "Branches",
  "belum dibatasi — melihat semua": "no limit set — sees everything",
  "Data": "Details",
  "Belum ada staf lain": "No other staff yet",
  "Tambahkan kepala cabang, supervisor, atau auditor.": "Add a branch manager, supervisor, or auditor.",
  "Simpan peran": "Save the role",
  "Pilih perannya dulu.": "Choose the role first.",
  "Peran disimpan": "Role saved",
  "Peran ini melihat SELURUH cabang. Daftar cabang tidak berlaku untuknya.": "This role sees EVERY branch. The branch list does not apply to it.",
  "Cabang yang menjadi urusannya": "The branches that are their business",
  "Pilih semua": "Select all",
  "Belum ada cabang dipilih — orang ini akan melihat SEMUA cabang.": "No branch chosen — this person will see EVERY branch.",
  "Ubah data staf": "Edit staff details",
  "mis. Kepala Cabang Surabaya": "e.g. Branch Manager, Surabaya",
  "Masih bekerja di sini": "Still works here",
  "Yang dimatikan tidak bisa masuk lagi, tetapi seluruh catatannya tetap utuh — dan catatan yang menyebut namanya tidak boleh kehilangan orangnya.": "Someone switched off can no longer sign in, but all their records stay intact — and a record that names them must not lose the person it names.",
  "Dipakai untuk masuk. Sandi sementara dibuatkan otomatis dan ditampilkan sekali saja.": "Used to sign in. A temporary password is generated automatically and shown once only.",
  "Bisa diubah kapan saja sesudahnya. Cabangnya diatur lewat tombol Peran setelah akunnya jadi.": "Changeable at any time afterwards. Their branches are set with the Role button once the account exists.",
  "Data staf diperbarui": "Staff details updated",
  "Akun dibuat": "Account created",
  "Sandi sementara hanya ditampilkan sekali ini.": "The temporary password is shown this once only.",
  "Serahkan kepada orangnya, dan ia wajib menggantinya saat pertama masuk. Sesudah jendela ini ditutup, sandinya tidak bisa dibaca lagi dari mana pun.": "Hand it to the person, and they must change it on first sign-in. Once this window closes, the password cannot be read anywhere again.",
  "Sudah saya catat": "I have written it down",
  "Seluruh halaman, seluruh cabang, dan satu-satunya yang boleh mengatur hak akses staf lain.": "Every page, every branch, and the only one who may set other staff's access rights.",
  "Seluruh cabang, seluruh halaman kecuali pengaturan hak akses.": "Every branch, every page except the access-rights settings.",
  "Hanya cabang yang ditugaskan kepadanya. Melihat biaya dan tagihan cabangnya, TIDAK melihat penggajian — daftar gaji rekan sekantor adalah hal yang paling cepat merusak suasana kerja.": "Only the branches assigned to them. Sees their branches' cost and invoices, but NOT payroll — a list of colleagues' wages is the fastest way to sour a workplace.",
  "Cabang yang ditugaskan. Menyusun jadwal, memeriksa mutu, dan mengurus bahan — tidak menyentuh keuangan.": "The branches assigned to them. Builds schedules, checks quality, and handles consumables — never touches finance.",
  "Cabang yang ditugaskan. Hanya pekerjaan harian dan mutu — yang ia butuhkan untuk memimpin regunya di lapangan.": "The branches assigned to them. Daily work and quality only — what they need to lead their crew in the field.",
  "MELIHAT seluruh cabang dan seluruh halaman, dan TIDAK BOLEH mengubah apa pun. Pemeriksa yang bisa mengubah bukan pemeriksa.": "SEES every branch and every page, and may NOT change anything. An examiner who can change things is not an examiner.",
  "Yang disentuh tiap hari: kehadiran, aduan penghuni, ronda, dan tugas.": "What gets touched daily: attendance, occupant reports, patrols, and tasks.",
  "Inspeksi mutu, penilaian kinerja, dan pelatihan petugas.": "Quality inspection, performance review, and attendant training.",
  "Jadwal, area yang dipantau, beban kerja, dan daftar petugas.": "Schedules, monitored areas, workload, and the attendant list.",
  "Bahan habis pakai, penerimaan barang dari pemasok, dan peralatan.": "Consumables, goods received from suppliers, and equipment.",
  "Daftar cabang, areanya, bangunan, lantai, ruangan, dan objek.": "The branch list, their areas, buildings, floors, rooms, and objects.",
  "Penggajian, tagihan, biaya kebersihan, dan kontrak. Kelompok yang paling sering tidak seharusnya dibuka semua orang.": "Payroll, invoices, cleaning cost, and contracts. The group that most often should not be open to everyone.",
  "Laporan bulanan dan portal untuk pemilik gedung.": "Monthly reports and the building owner's portal.",
  "Data perusahaan dan pengaturan korporat.": "Company details and corporate settings.",
