  "Keduanya akan saling membawahi.": "The two would end up managing each other.",
  "Ruangan itu bukan tanggung jawab Anda.": "That room is not your responsibility.",
  "Pilih tingkat kepuasannya dulu.": "Choose how satisfied you are first.",
  "Atasan": "Reports to",
  "Bawahannya belum punya cabang untuk diambil.": "Their reports have no branches to take.",
  "Belum ada {p} yang bisa dijadikan atasannya.": "There is no {p} yet to report to.",
  "Ambil dari bawahannya": "Take from their reports",
  "Ruangan yang menjadi tanggung jawab Anda.": "The rooms you are responsible for.",
  "Di sini Anda melihat kapan terakhir dibersihkan, melaporkan yang kurang, dan memberi tahu seberapa bersih hasilnya.": "Here you see when they were last cleaned, report what is lacking, and say how clean the result is.",
  "Penilaian Anda tidak menghukum siapa pun — ia dipakai melihat ruangan mana yang jadwalnya perlu ditambah.": "Your rating punishes nobody — it is used to see which rooms need more time on the schedule.",
  "Belum ada ruangan yang ditetapkan untuk Anda": "No room has been assigned to you yet",
  "Hubungi staf gedung agar ruangan Anda didaftarkan. Selama belum ditetapkan, halaman ini sengaja kosong — menampilkan ruangan orang lain akan lebih buruk daripada tidak menampilkan apa-apa.": "Ask the building staff to register your room. Until then this page is deliberately empty — showing you someone else's room would be worse than showing nothing.",
  "Terakhir dibersihkan": "Last cleaned",
  "belum pernah tercatat": "never recorded",
  "Kepuasan rata-rata": "Average satisfaction",
  "belum cukup penilaian untuk dirata-rata": "not enough ratings to average yet",
  "Laporkan yang kurang, bukan yang jelek saja.": "Report what is lacking, not only what is bad.",
  "Setiap laporan punya batas waktu tanggapan, diteruskan ke petugas yang bertanggung jawab, dan bisa Anda ikuti sampai ditutup. Foto sangat membantu — satu foto menghemat tiga kali bolak-balik.": "Every report has a response deadline, goes to the attendant responsible, and you can follow it until it is closed. A photo helps enormously — one photo saves three rounds of back-and-forth.",
  "Laporan baru": "New report",
  "Bila ada yang kurang di ruangan Anda, laporkan di sini.": "If something is lacking in your room, report it here.",
  "sudah lewat batas waktu tanggapan": "past the response deadline",
  "Tanggapan": "Response",
  "Yang Anda nilai adalah RUANGAN, bukan orangnya.": "What you rate is the ROOM, not the person.",
  "Anda melihat hasilnya; Anda tidak melihat berapa menit ruangan ini dijatah, apakah bahannya habis, atau apa yang terjadi sebelum petugas datang. Karena itu penilaian Anda dipakai menemukan ruangan yang perlu perhatian — bukan untuk menghukum seseorang.": "You see the result; you do not see how many minutes this room is allotted, whether the supplies ran out, or what happened before the attendant arrived. So your rating is used to find rooms that need attention — not to punish anyone.",
  "Nilai hari ini": "Rate today",
  "Penilaian Anda": "Your ratings",
  "Penilaian": "Ratings",
  "Belum ada penilaian": "No ratings yet",
  "Nilai ruangan Anda setelah dibersihkan.": "Rate your room after it has been cleaned.",
  "Laporkan yang kurang": "Report what is lacking",
  "Seberapa mendesak": "How urgent",
  "Ini menentukan batas waktu tanggapan. Menandai semuanya mendesak membuat yang sungguh mendesak tidak lagi menonjol.": "This sets the response deadline. Marking everything urgent stops the genuinely urgent from standing out.",
  "Apa yang kurang?": "What is lacking?",
  "mis. Lantai dekat pintu masuk masih ada bekas oli sejak kemarin.": "e.g. The floor by the entrance still has oil marks from yesterday.",
  "Laporan terkirim": "Report sent",
  "Seberapa bersih ruangan ini?": "How clean is this room?",
  "Anda sudah menilai ruangan ini hari ini. Menilai lagi akan mengganti penilaian sebelumnya, bukan menambahkannya.": "You have already rated this room today. Rating again replaces the earlier one, it does not add to it.",
  "Catatan (opsional)": "Note (optional)",
  "yang paling perlu diperbaiki menurut Anda": "what most needs putting right, in your view",
  "Penilaian ini melekat pada RUANGAN dan tanggalnya, bukan pada nama petugas. Ia dipakai melihat ruangan mana yang jadwalnya perlu ditambah.": "This rating attaches to the ROOM and its date, not to an attendant's name. It is used to see which rooms need more time on the schedule.",
  "Kirim penilaian": "Send rating",
  "Penilaian diperbarui": "Rating updated",
  "Terima kasih": "Thank you",
  "Area Manager": "Area Manager",
  "Membawahi beberapa Kepala Cabang. Melihat seluruh cabang di wilayahnya beserta biaya, tagihan, dan laporannya — tetapi tidak penggajian, dengan alasan yang sama seperti Kepala Cabang.": "Manages several Branch Managers. Sees every branch in their region along with its cost, invoices, and reports — but not payroll, for the same reason as a Branch Manager.",
  "Supervisor": "Supervisor",
  "Ruangan Saya": "My Rooms",
