  /* ======================================================================
     PESAN KELUAR (wa.js) — bukan teks layar
     ----------------------------------------------------------------------
     Kunci di bawah ini dipakai oleh template WhatsApp, dan bahasanya
     dipilih menurut PENERIMA pesan (I18N.pesanUntuk), bukan menurut bahasa
     layar orang yang menekan tombol kirim. Admin berbahasa Inggris yang
     mengirimi pelanggan Indonesia harus menghasilkan pesan Indonesia.

     Ditaruh di berkas yang sama dengan teks antarmuka karena kamusnya
     memang satu — dipisahkan hanya oleh judul ini, supaya jelas bahwa
     kalimat di bagian ini dibaca orang di luar aplikasi dan karena itu
     kesalahan terjemahannya lebih mahal.
     ====================================================================== */
