  /* ======================================================================
     NAMA JENIS PESAN (WA.LABEL) — ini justru TEKS LAYAR
     ----------------------------------------------------------------------
     Kebalikan dari bagian di atasnya. Yang di atas adalah ISI pesan, dibaca
     penerimanya. Yang di bawah ini adalah NAMA JENIS pesannya — “Konfirmasi
     permintaan masuk”, “Pengingat H-1” — yang hanya muncul sebagai chip di
     daftar WhatsApp Outbox dan dibaca ADMIN, bukan penerima.

     Karena itu ia mengikuti bahasa LAYAR, dan dibungkus I18N.t() di tempat
     menggambar. Sebelumnya nilainya dipakai apa adanya, sehingga admin
     berbahasa Inggris melihat daftar berbahasa Indonesia — cacat yang tidak
     terlihat karena berkas wa.js seluruhnya dikecualikan dari audit i18n.
     ====================================================================== */
  "Konfirmasi permintaan masuk": "Request received — confirmation",
  "Jadwal survei lokasi": "Site survey scheduled",
  "Pengiriman penawaran harga": "Quotation sent",
