  /* ======================================================================
     SISA wa.js — galat penyusunan dan toast pengirim
     ----------------------------------------------------------------------
     Tiga yang pertama adalah kalimat yang muncul ketika template GAGAL
     disusun. Terlihat seperti pesan pengembang, tetapi bukan: nilainya
     dikembalikan sebagai ISI pesan dan tersimpan di outbox, jadi bisa
     benar-benar terkirim kepada pelanggan bila ada yang menekan Kirim tanpa
     membacanya. Karena itu bahasanya mengikuti penerima.

     Tiga yang terakhir kebalikannya — toast di layar orang yang menekan
     tombolnya, jadi mengikuti bahasa layar.
     ====================================================================== */
  "template": "template",
  "tidak ditemukan": "not found",
  "gagal menyusun pesan": "failed to compose the message",
  "Nomor penerima tidak ada": "The recipient has no phone number",
  "WhatsApp dibuka untuk": "WhatsApp opened for",
  "Tandai terkirim": "Mark as sent",

  /* ======================================================================
     BADAN SUREL (email.js) — dibaca klien, bukan admin
     ----------------------------------------------------------------------
     Aturannya sama dengan bagian pesan keluar di atas: bahasanya ditentukan
     PENERIMA. Yang membuat bagian ini layak disebut sendiri adalah sejarahnya
     — email.js sempat SETENGAH dibungkus I18N.t(), sehingga sebagian label
     mengikuti bahasa layar pengirim sementara sebagian lain tidak
     diterjemahkan sama sekali, dan satu tabel yang sama bisa memuat
     “SUBTOTAL PRODUCT PRICE” tepat di atas “Diskon”.

     Satu kunci di bawah ini menyangkut PAJAK. Terjemahannya dibuat model AI
     dan wajib ditinjau penutur asli sebelum dipakai pelanggan sungguhan —
     alasannya sama dengan yang tertulis di kepala lang/core.js.
     ====================================================================== */
  /* Bukan "Payment reminders" — lihat alasannya di email.js. */
  "Pengingat pembayaran invoice": "Payment reminder for invoice",
  "Berat": "Weight",
  "Penjual": "Seller",
