  "Pembayaran bisa dilakukan lewat aplikasi EXOCLEAN pada menu Tagihan.": "Payment can be made through the EXOCLEAN app under Bills.",
  "Buka aplikasi EXOCLEAN pada menu Tagihan untuk membayar.": "Open the EXOCLEAN app under Bills to pay.",
  "berikut penawaran yang Anda minta. Silakan tinjau rinciannya di aplikasi EXOCLEAN — persetujuan dilakukan di sana supaya tercatat rapi untuk kedua pihak.": "here is the quotation you asked for. Please review the details in the EXOCLEAN app — approval happens there so both sides have a clean record.",
  "Harga di atas berlaku sampai tanggal yang tertera. Setelah itu kami perlu menghitung ulang — bukan untuk menaikkan harga, melainkan karena biaya bahan dan tenaga memang berubah.": "The prices above hold until the date shown. After that we need to recalculate — not to raise the price, but because material and labour costs genuinely move.",
  "Butuh penyesuaian? Balas surat ini. Kami lebih suka merevisi penawaran daripada mengerjakan sesuatu yang tidak sesuai harapan Anda.": "Need an adjustment? Reply to this email. We would rather revise the quotation than do work that does not match what you expected.",
  "Buka aplikasi EXOCLEAN pada menu Penawaran untuk menyetujui.": "Open the EXOCLEAN app under Quotations to approve.",
  "*Biaya-biaya yang merupakan bagian dari tagihan ini, jika ada, sudah termasuk Pajak Pertambahan Nilai (Ppn) sesuai tarif yang berlaku. Dokumen ini berfungsi sebagai Bukti Pemesanan dan/atau Pembelian.": "*Any charges forming part of this bill already include Indonesian Value Added Tax (Pajak Pertambahan Nilai / Ppn) at the applicable rate. This document serves as proof of order and/or purchase.",

  /* ======================================================================
     WAKTU RELATIF (utils.js)
     ----------------------------------------------------------------------
     Kolom waktu di hampir setiap daftar. Selama ini hanya ‘Hari ini’ yang
     dibungkus; ‘Besok’, ‘Kemarin’, dan ‘baru saja’ lolos audit karena
     penanda bahasanya mencari kata umum Indonesia dan ketiganya tidak
     memuat satu pun. Yang membuktikannya bukan alat, melainkan membuka
     layar WhatsApp Outbox dalam bahasa Inggris dan membaca “baru saja”.

     {n}, {j}, {m} disisipkan SESUDAH terjemahan diambil, sehingga bahasa
     yang menaruh angkanya di tempat lain tetap terlayani.
     ====================================================================== */
  "Besok": "Tomorrow",
  "Kemarin": "Yesterday",
  "baru saja": "just now",
  "{n} hari lalu": "{n} days ago",
  "{n} mnt lalu": "{n} min ago",
  "{n} jam lalu": "{n}h ago",
  "{j}j {m}m": "{j}h {m}m",

  /* ======================================================================
     SINGKATAN BULAN (utils.js)
     ----------------------------------------------------------------------
     Nama panjang bulan dan hari sudah ada di berkas ini sejak lama; yang
     belum adalah SINGKATANNYA — dan justru singkatan yang dipakai U.tgl(),
     bentuk tanggal yang paling sering muncul. Akibatnya surel berbahasa
     Inggris yang seluruh kalimatnya sudah benar tetap menuliskan
     “Due: 21 Des 2025”.

     Sebagian memetakan ke dirinya sendiri (Jan, Feb, Sep). Itu disengaja:
     kunci yang ada tetapi bernilai sama lebih baik daripada kunci yang
     hilang, karena yang hilang tidak terlihat sampai ada yang membacanya.
     ====================================================================== */
  "Jan": "Jan",
  "Feb": "Feb",
