  "Angka di bawah ini milik SELURUH korporat, bukan cabang Anda.": "The figures below cover the WHOLE company, not your branch.",
  "Bahan belum pernah dicatat berada di gudang mana — selama itu, tidak ada satu pun angka per cabang yang bisa dihitung. Catat penempatannya lewat Penerimaan Barang atau Pindah Gudang supaya saldo cabang mulai berarti.": "No consumable has ever been recorded as sitting in a particular warehouse — until that happens, no per-branch figure can be calculated at all. Record placement through Goods Receipt or Move Warehouse so branch balances start to mean something.",
  "Angka di bawah ini milik cabang Anda.": "The figures below are for your branch.",
