  "Barang itu belum pernah dicatat berada di gudang mana pun — selama itu, tidak ada satu pun angka per cabang yang bisa dihitung untuknya. Catat penempatannya lewat Penerimaan Barang atau Pindah Gudang supaya saldo cabang mulai berarti.": "Those items have never been recorded as sitting in any warehouse — until that happens, no per-branch figure can be calculated for them. Record placement through Goods Receipt or Move Warehouse so branch balances start to mean something.",
  "Selebihnya milik cabang Anda.": "The rest are your branch's.",

